import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load the API specification for validation
API_SPEC_PATH = "api.json"
validator = SwaggerSchemaValidator(API_SPEC_PATH)

# Load test data from JSON file
_here = Path(__file__).resolve().parent
_ENDPOINT_DATA_PATH = _here / "store_order.json"

def _load_json_file(path):
    with open(path, 'r') as file:
        return json.load(file)

_ENDPOINT_DATA = _load_json_file(_ENDPOINT_DATA_PATH)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [f"scenario_{i['id']}" for i in _ENDPOINT_DATA]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_place_order(api_client, config_test_data, scenario_case):
    """
    Test the /store/order endpoint with various scenarios.
    """
    # Merge default test data with scenario specific data
    test_data = {**config_test_data, **scenario_case}

    # Prepare request payload
    payload = {
        "id": test_data.get("id"),
        "petId": test_data.get("petId"),
        "quantity": test_data.get("quantity"),
        "shipDate": test_data.get("shipDate"),
        "status": test_data.get("status"),
        "complete": test_data.get("complete")
    }

    # Validate request payload against schema
    validator.validate_json(payload, "Order")

    # Make API request
    response = api_client.post("/store/order", data=payload)

    # Validate response status code
    assert response.status_code == test_data["statusCode"], f"Unexpected status code: {response.status_code}"

    # Validate response schema
    validation_result = validator.validate_schema_by_response("/store/order", "post", str(response.status_code), response)
    assert validation_result["valid"], f"Response schema validation failed: {validation_result.get('message')}"

    # Additional assertions based on scenario
    if test_data["statusCode"] == 200:
        response_data = response.json()
        assert response_data["id"] == test_data["id"], "Mismatch in order ID"
        assert response_data["petId"] == test_data["petId"], "Mismatch in pet ID"
        assert response_data["quantity"] == test_data["quantity"], "Mismatch in quantity"
        assert response_data["status"] == test_data["status"], "Mismatch in status"
        assert response_data["complete"] == test_data["complete"], "Mismatch in completion status"

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_place_order_invalid_auth(api_client, scenario_case):
    """
    Test the /store/order endpoint with invalid authentication.
    """
    # Prepare request payload
    payload = {
        "id": scenario_case.get("id"),
        "petId": scenario_case.get("petId"),
        "quantity": scenario_case.get("quantity"),
        "shipDate": scenario_case.get("shipDate"),
        "status": scenario_case.get("status"),
        "complete": scenario_case.get("complete")
    }

    # Validate request payload against schema
    validator.validate_json(payload, "Order")

    # Make API request with invalid auth
    response = api_client.post("/store/order", data=payload, headers={"Authorization": "Bearer invalid_token"})

    # Validate response status code for unauthorized access
